STACKS = ["React+Vite", "Next.js", "纯HTML+JS", "Python全栈"]
DIMS = ["生成速度", "一次通过率", "可维护性", "部署简单度", "生态成熟度"]
# 每维 1-5 分, 5 最好; "部署简单度"已统一方向: 分高 = 部署越省事
SCORES = {
    "React+Vite": {"生成速度": 4, "一次通过率": 4, "可维护性": 4, "部署简单度": 4, "生态成熟度": 5},
    "Next.js":    {"生成速度": 3, "一次通过率": 3, "可维护性": 4, "部署简单度": 4, "生态成熟度": 5},
    "纯HTML+JS":  {"生成速度": 5, "一次通过率": 4, "可维护性": 2, "部署简单度": 5, "生态成熟度": 3},
    "Python全栈": {"生成速度": 4, "一次通过率": 3, "可维护性": 4, "部署简单度": 3, "生态成熟度": 4},
}
BASE = {"生成速度": 0.15, "一次通过率": 0.25, "可维护性": 0.30, "部署简单度": 0.15, "生态成熟度": 0.15}
PROTO = {"生成速度": 0.35, "一次通过率": 0.25, "可维护性": 0.05, "部署简单度": 0.25, "生态成熟度": 0.10}

def ranking(weights):
    totals = {s: round(sum(SCORES[s][d] * w for d, w in weights.items()), 2) for s in STACKS}
    return sorted(STACKS, key=lambda s: (-totals[s], s)), totals

def sensitivity(base, delta=0.05):
    """单维权重上下调 delta 后归一化重排, 报告冠军是否翻转。"""
    flips = []
    base_rank, _ = ranking(base)
    for dim in DIMS:
        for direction in ("上调", "下调"):
            w = dict(base)
            w[dim] = w[dim] + (delta if direction == "上调" else -delta)
            total = sum(w.values())
            w = {d: v / total for d, v in w.items()}
            new_rank, _ = ranking(w)
            if new_rank[0] != base_rank[0]:
                flips.append(f"{dim}{direction} -> 冠军翻转为 {new_rank[0]}")
    return flips

def show(title, weights):
    rank, totals = ranking(weights)
    print(f"== {title} ==")
    for i, s in enumerate(rank, 1):
        print(f"{i}. {s:<12} 加权总分 {totals[s]:.2f}")
    flips = sensitivity(weights)
    if flips:
        for f in flips:
            print(f"  [敏感性] {f}")
    else:
        print("  敏感性: 单维权重 ±0.05 扰动下冠军稳定")
    print()

show("基准权重(要长期维护的正式产品)", BASE)
show("原型优先(一周验证期, 用完即弃)", PROTO)

