def weighted_rank(scores, weights):
    total_w = sum(weights.values())
    totals = {}
    for stack, dim_scores in scores.items():
        totals[stack] = round(sum(dim_scores[d] * w / total_w for d, w in weights.items()), 2)
    return sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))

